 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find horizontal pattern rows and fill only enclosed one-cell gaps in their runs.
    pattern_rows = []
    for r, row in enumerate(grid):
        colors = [v for v in row if v]
        if len(colors) < 2:
            continue
        # A pattern row contains one or more contiguous runs of nonzero cells.
        runs = []
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            color = row[c]
            start = c
            while c < w and row[c] == color:
                c += 1
            runs.append((start, c - 1, color))
        if len(runs) >= 2:
            pattern_rows.append(r)
            for (a, b, col), (x, y, col2) in zip(runs, runs[1:]):
                if col == col2 and x == b + 2 and grid[r][b + 1] == 0:
                    g[r][b + 1] = col
    # For every gap column between same-color horizontal runs, propagate that
    # horizontal color toward the previous stripe/top; the lower vertical stem
    # supplies the color below the final horizontal stripe.
    gapcols = set()
    for r in pattern_rows:
        row = grid[r]
        runs = []
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            col = row[c]
            a = c
            while c < w and row[c] == col:
                c += 1
            runs.append((a, c - 1, col))
        for (a, b, col), (x, y, col2) in zip(runs, runs[1:]):
            if col == col2 and x == b + 2 and grid[r][b + 1] == 0:
                gapcols.add(b + 1)
    for col in gapcols:
        stripes = [r for r in pattern_rows if g[r][col] != 0]
        if not stripes:
            continue
        # Determine the lower stem color from the nonzero vertical cells beneath
        # the last horizontal stripe, if present.
        last = stripes[-1]
        below_colors = [grid[r][col] for r in range(last + 1, h) if grid[r][col] != 0]
        lower = below_colors[0] if below_colors else 0
        # Horizontal stripe colors fill upward from each stripe to the preceding
        # stripe boundary. The bottom stem color fills below the last stripe.
        for i, r in enumerate(stripes):
            upper = 0 if i == 0 else stripes[i - 1] + 1
            color = g[r][col]
            for rr in range(upper, r + 1):
                g[rr][col] = color
        if lower:
            for rr in range(last + 1, h):
                g[rr][col] = lower
    return g

